  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H_sqrt",
        "statement": "Period is proportional to the square root of length: T = 2.006*sqrt(length_m), independent of bob mass and release angle in the calibrated range.",
        "confidence": 0.75
      },
      {
        "hypothesis_id": "H_linear",
        "statement": "Period is proportional to length: T = 2.006*length_m, independent of bob mass and release angle.",
        "confidence": 0.15
      },
      {
        "hypothesis_id": "H_constant",
        "statement": "Period is constant at 2.006 s, independent of length, bob mass, and release angle.",
        "confidence": 0.10
      }
    ]
  },
  "experiment": {
    "intent": "Vary length at fixed small mass and angle to test whether period scales as sqrt(length), linearly with length, or is constant.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 2.0,
      "bob_mass_kg": 0.2,
      "release_angle_deg": 5.0
    },
    "readouts": ["period_s"],
    "replicates": 10,
    "forecasts": {
      "H_sqrt": {
        "period_s": 2.837
      },
      "H_linear": {
        "period_s": 4.012
      },
      "H_constant": {
        "period_s": 2.006
      }
    }
  },
  "final": null
}

